def norm(w):
    w = w.strip().lower()
    return w

l2 = set(norm(w) for w in L2.replace("\n", ",").split(",") if w.strip())
full_raw = [norm(w) for w in FULL.replace("\n", ",").split(",") if w.strip()]
seen = set()
full = []
for w in full_raw:
    if w and w not in seen:
        seen.add(w)
        full.append(w)

print("二级词汇数:", len(l2))
print("三级表去重后总词数:", len(full))
missing_l2_in_full = l2 - seen
print("二级词不在三级表中的:", sorted(missing_l2_in_full))
# 初中词 = full - l2
middle = [w for w in full if w not in l2]
print("初中阶段词数:", len(middle))
